"use client";

import React, { useRef } from "react";
import ServicesCard from "@/app/components/ServicesCard";
import img1 from "@/assets/s1.png";
import img2 from "@/assets/s2.png";
import img3 from "@/assets/s3.png";
import img4 from "@/assets/s4.png";
import { StaticImageData } from "next/image";

interface Service {
  title: string;
  img: StaticImageData;
}

const services: Service[] = [
  {
    title: "Installation",
    img: img1,
  },
  {
    title: "Maintenance",
    img: img2,
  },
  {
    title: "Repair",
    img: img3,
  },
  {
    title: "Consultation",
    img: img4,
  },
  {
    title: "AMC",
    img: img4,
  },
];

const Services: React.FC = () => {
  const scrollRef = useRef<HTMLDivElement>(null);

  const scrollLeft = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({ left: -300, behavior: "smooth" });
    }
  };

  const scrollRight = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({ left: 300, behavior: "smooth" });
    }
  };

  return (
    <section className="my-20 text-center relative">
      {/* Heading */}
      <h1 className="py-8 text-5xl font-bold animate-slideIn">Our Services</h1>
      {/* Buttons */}
      <div className="flex items-center justify-between space-x-4 my-4 absolute">
        <div onClick={scrollLeft} className="px-4 py-2">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={1.5}
            stroke="currentColor"
            className="size-10 hover:bg-gray-60 cursor-pointer"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M15.75 19.5 8.25 12l7.5-7.5"
            />
          </svg>
        </div>
        <div onClick={scrollRight} className="px-4 py-2">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={1.5}
            stroke="currentColor"
            className="size-10 hover:bg-gray-60 cursor-pointer"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="m8.25 4.5 7.5 7.5-7.5 7.5"
            />
          </svg>
        </div>
      </div>
      {/* Horizontal Scrollable Cards */}
      <div
        ref={scrollRef}
        className="flex overflow-hidden gap-6 px-4 relative"
        style={{ scrollBehavior: "smooth" }}
      >
        {services.map((service, index) => (
          <div key={index} className="flex-shrink-0 w-64">
            <ServicesCard title={service.title} img={service.img} />
          </div>
        ))}
      </div>
    </section>
  );
};

export default Services;
